/**
 * ۳۱. قهرمان زمان ما — میخائیل لرمانتوف
 */
object Story31 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_hero_of_our_time",
        chapters = listOf(
            chapter1(),
            chapter2(),
            chapter3(),
            chapter4(),
            chapter5(),
            chapter6(),
        )
    )

    // ─────────── فصل ۱: بلا ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Bela", titlePersian = "بلا",
        paragraphs = listOf(
            StoryParagraph("I was journeying through the Caucasus by carriage in the autumn of that year, and the monotony of the road had begun to weigh upon me with an almost physical oppression.", "در پاییز آن سال با کالسکه از میان کوه‌های قفقاز سفر می‌کردم و یکنواختی جاده با فشاری تقریباً جسمی بر من سنگینی می‌کرد."),
            StoryParagraph("The landscape unfolded before my eyes in a succession of barren peaks and precipitous gorges, and the wind, howling through the passes, seemed to carry with it the accumulated melancholy of centuries.", "منظره در برابر چشمانم در توالی قله‌های بایر و دره‌های پرتگاهی گسترده می‌شد و باد که از میان گذرگاه‌ها زوزه می‌کشید، به نظر می‌رسید مالیخولیای انباشته قرن‌ها را با خود حمل می‌کند."),
            StoryParagraph("There is a particular solitude to be found in mountains, a solitude that is not merely the absence of company but the presence of something vast and indifferent.", "در کوه‌ها نوع خاصی از تنهایی یافت می‌شود، تنهایی‌ای که فقط نبودِ همراه نیست، بلکه حضور چیزی عظیم و بی‌تفاوت است."),
            StoryParagraph("I was a young officer in the imperial Russian army, dispatched to this wild and inhospitable frontier, and I was filled with that peculiar mixture of ambition and unease that afflicts every young man far from home.", "من افسر جوانی در ارتش امپراتوری روسیه بودم که به این مرز وحشی و ناسازگار فرستاده شده بودم و پر از آن آمیزه عجیب جاه‌طلبی و ناآرامی بودم که هر جوان دور از خانه را مبتلا می‌کند."),
            StoryParagraph("My traveling companion was an old staff captain named Maxim Maximych, a man whose weathered face and unhurried speech betrayed a life spent in the service of a vast and indifferent empire.", "همراه سفرم ناخدای ستاد پیری به نام ماکسیم ماکسیمیچ بود، مردی که صورت هوازده و گفتار آهسته‌اش نشان از عمری در خدمت امپراتوری‌ای وسیع و بی‌تفاوت داشت."),
            StoryParagraph("He had been stationed in the Caucasus for so many years that the mountains had ceased to be exotic to him, and he had come to regard the Circassian tribes with that ambiguous mixture of contempt and respect that only familiarity can produce.", "او آنقدر سال‌ها در قفقاز مستقر بوده بود که کوه‌ها برایش از حالت بیگانه خارج شده بودند و به قبایل چرکس با آن آمیزه مبهم تحقیر و احترام می‌نگریست که تنها آشنایی می‌تواند ایجاد کند."),
            StoryParagraph("To relieve the tedium of our journey, he began to recount the story of a certain officer whom he had once known, a man of extraordinary intelligence and even more extraordinary moral complexity.", "برای کاستن از یکنواختی سفرمان، شروع کرد به تعریف داستان افسر خاصی که زمانی می‌شناخته، مردی با هوش استثنایی و پیچیدگی اخلاقی حتی استثنایی‌تر."),
            StoryParagraph("'His name,' said Maxim Maximych, 'was Grigory Alexandrovich Pechorin, and I have never in my life encountered a more contradictory human being.'", "ماکسیم ماکسیمیچ گفت: «نامش گریگوری آلکساندراویچ پچورین بود و در عمرم هرگز موجود انسانی متناقض‌تری ندیده‌ام.»"),
            StoryParagraph("As we traveled through the desolate passes, he proceeded to narrate the events that had brought Pechorin to this remote garrison, and the strange tragedy that had unfolded there.", "در حالی که از گذرگاه‌های متروک می‌گذشتیم، شروع کرد به روایت رویدادهایی که پچورین را به این پادگان دورافتاده آورده بود و تراژدی عجیبی که در آنجا رخ داده بود."),
            StoryParagraph("Pechorin, he explained, was a man who had been endowed by nature with every gift that could make a man enviable among his fellows.", "او توضیح داد که پچورین مردی بود که طبیعت هر موهبتی را که می‌تواند انسانی را در میان همنوعانش قابل حسادت کند به او عطا کرده بود."),
            StoryParagraph("He was handsome in that careless, aristocratic manner that women find irresistible, and he possessed an intellect of such penetrating acuity that nothing escaped his observation.", "او به آن شیوه بی‌خیال و اشرافی زیبا بود که زنان آن را مقاومت‌ناپذیر می‌یابند و از چنان تیزی نافذی برخوردار بود که هیچ چیز از مشاهده‌اش نمی‌گریخت."),
            StoryParagraph("He could read a man's character in a single glance, and he could predict a woman's weakness with the accuracy of a mathematician solving an equation.", "می‌توانست شخصیت یک مرد را در یک نگاه بخواند و ضعف یک زن را با دقت ریاضیدانی که معادله‌ای را حل می‌کند پیش‌بینی کند."),
            StoryParagraph("And yet, for all his advantages, he was afflicted by a profound and incurable ennui, a spiritual emptiness that no pleasure could fill and no achievement could alleviate.", "و با این حال، با تمام مزایایش، مبتلا به ملالی عمیق و علاج‌ناپذیر بود، پوچی روحی‌ای که هیچ لذتی نمی‌توانست پرش کند و هیچ دستاوردی تسکینش دهد."),
            StoryParagraph("He had tried, in his youth, to find meaning in the pursuit of pleasure, but pleasure had quickly become tedious, as it always does when pursued for its own sake.", "او در جوانی تلاش کرده بود معنا را در جستجوی لذت بیابد، اما لذت به‌سرعت یکنواخت شده بود، همانطور که همیشه وقتی برای خودش دنبال شود می‌شود."),
            StoryParagraph("He had tried to find meaning in ambition, in the pursuit of power and distinction, but he had discovered, to his chagrin, that he did not truly care whether he succeeded or failed.", "تلاش کرده بود معنا را در جاه‌طلبی، در جستجوی قدرت و امتیاز بیابد، اما با تأسف کشف کرده بود که واقعاً برایش مهم نیست موفق شود یا شکست بخورد."),
            StoryParagraph("He had tried to find meaning in books and learning, but the more he learned, the more he understood that knowledge without purpose is merely a more sophisticated form of ignorance.", "تلاش کرده بود معنا را در کتاب و دانش بیابد، اما هرچه بیشتر می‌آموخت، بیشتر می‌فهمید که دانش بدون هدف فقط شکل پیچیده‌تری از جهل است."),
            StoryParagraph("And so he had come to the Caucasus, not out of any desire for adventure or duty, but simply because he could think of nothing better to do.", "و بنابراین به قفقاز آمده بود، نه از هیچ تمایلی به ماجراجویی یا وظیفه، بلکه صرفاً چون نمی‌توانست کار بهتری به ذهنش برسد."),
            StoryParagraph("At the fort where Maxim Maximych was stationed, Pechorin soon found a distraction in the form of a young Circassian woman named Bela.", "در قلعه‌ای که ماکسیم ماکسیمیچ مستقر بود، پچورین به‌زودی سرگرمی‌ای در قالب زن جوان چرکسی به نام بلا یافت."),
            StoryParagraph("Bela was the daughter of a local prince, and she possessed a beauty that was at once delicate and untamed, like a wildflower growing in the crevice of a cliff.", "بلا دختر شاهزاده‌ای محلی بود و زیبایی‌ای داشت که همزمان لطیف و رام‌نشده بود، مثل گل وحشی که در شکاف صخره‌ای می‌روید."),
            StoryParagraph("Her eyes were dark and bright with the fire of a spirit that had never been broken, and her movements had the unstudied grace of someone who had never learned to perform for an audience.", "چشمانش تیره و روشن از آتش روحی بود که هرگز شکسته نشده بود و حرکاتش لطافت ناخودآگاهی داشت که از آنِ کسی است که هرگز برای تماشاگر اجرا نکرده."),
            StoryParagraph("At the wedding feast where they first met, Pechorin observed her with that cold, analytical gaze that was his habitual mode of apprehending the world, and he decided, with the casual cruelty of the deeply bored, that he would possess her.", "در ضیافت عروسی که اولین بار همدیگر را دیدند، پچورین با آن نگاه سرد و تحلیلی که شیوه معمولش برای درک دنیا بود تماشایش کرد و با خشونت بی‌خیالِ فردی عمیقاً کسل، تصمیم گرفت مالکش شود."),
            StoryParagraph("His method was characteristically indirect: he cultivated the friendship of Bela's brother, a wild and avaricious youth named Azamat, whose one consuming passion was to possess a certain magnificent horse owned by a Circassian warrior named Kazbich.", "روشش به‌طور مشخص غیرمستقیم بود: او دوستی برادر بلا را پرورد، جوانی وحشی و طمع‌کار به نام آزامات که تنها شور فراگیرش مالکیت اسب باشکوه خاصی بود که جنگجویی چرکسی به نام کازبیچ داشت."),
            StoryParagraph("The horse, Kazbich's Karagyoz, was more than an animal; it was a symbol of freedom and pride, the kind of horse that a Circassian would die to protect and kill to obtain.", "آن اسب، کاراگیوزِ کازبیچ، چیزی بیش از یک حیوان بود؛ نمادی از آزادی و غرور، اسبی از آن نوع که یک چرکسی برای محافظتش می‌میرد و برای به دست آوردنش می‌کشد."),
            StoryParagraph("Pechorin, recognizing in this desire a lever with which to move the young man, proposed a bargain of exquisite villainy: Azamat would deliver Bela to him, and Pechorin would help him steal the horse.", "پچورین که در این میل اهرمی برای حرکت دادن آن جوان تشخیص داده بود، معامله‌ای با شرارت ناب پیشنهاد داد: آزامات بلا را به او تحویل دهد و پچورین به او کمک کند اسب را بدزدد."),
            StoryParagraph("The scheme was executed with that mechanical precision that Pechorin brought to all his undertakings, and within a few days, Bela was installed in the fort, and Azamat had fled into the mountains with his stolen prize.", "نقشه با همان دقت مکانیکی که پچورین در همه کارهایش به کار می‌برد اجرا شد و در عرض چند روز، بلا در قلعه مستقر شد و آزامات با جایزه دزدیده‌اش به کوه‌ها فرار کرده بود."),
            StoryParagraph("Bela, torn from her family and her culture, was at first inconsolable; she refused food, refused speech, refused to acknowledge the existence of her captor.", "بلا که از خانواده و فرهنگش ربوده شده بود، ابتدا تسلی‌ناپذیر بود؛ از غذا امتناع می‌کرد، از صحبت کردن، از به رسمیت شناختن وجود رباینده‌اش."),
            StoryParagraph("She sat in the corner of the room like a wounded animal, her dark eyes fixed on the distance, and she would not permit anyone to approach her.", "در گوشه اتاق مثل حیوانی زخمی می‌نشست، چشمان تیره‌اش به دور خیره بود و به هیچ‌کس اجازه نزدیک شدن نمی‌داد."),
            StoryParagraph("But Pechorin was patient, as only a man with nothing else to occupy his attention can be patient, and he set about winning her trust with a calculated gentleness that was perhaps more cruel than outright violence.", "اما پچورین صبور بود، همانطور که تنها مردی با هیچ چیز دیگری برای جلب توجهش می‌تواند صبور باشد، و شروع کرد به جلب اعتمادش با لطافتی محاسبه‌شده که شاید بی‌رحمانه‌تر از خشونت آشکار بود."),
            StoryParagraph("He learned her language, adopted her customs, spoke to her of the world beyond the mountains with that eloquence that he could summon whenever he chose.", "زبانش را یاد گرفت، آدابش را پذیرفت، با آن فصاحتی که هر وقت می‌خواست می‌توانست فراخواند از دنیای فراتر از کوه‌ها برایش صحبت کرد."),
            StoryParagraph("He brought her gifts, not of gold or jewels, which she would have refused, but of small things: a shawl embroidered with flowers, a songbird in a wicker cage, a mirror with an ivory frame.", "برای او هدایایی آورد، نه از طلا و جواهر که رد می‌کرد، بلکه چیزهای کوچک: شالچه‌ای با گل‌های گلدوزی، پرنده‌ای آوازخوان در قفسی بافته، آینه‌ای با قاب عاجی."),
            StoryParagraph("And slowly, inevitably, Bela began to love him — as so many women would come to love Pechorin — with a love that was total, unreserved, and utterly destructive.", "و به‌آرامی، اجتناب‌ناپذیر، بلا شروع کرد به عشق ورزیدن به او — همانطور که بسیاری زنان به پچورین عشق ورزیدند — با عشقی که کامل، بی‌قید و شرط و کاملاً مخرب بود."),
            StoryParagraph("For a season, Pechorin seemed content with his conquest; he treated her with a tenderness that surprised even Maxim Maximych, and for a while, the old captain allowed himself to hope that the young officer had finally found something worth living for.", "برای فصلی، پچورین با فتحش راضی به نظر می‌رسید؛ با لطافتی با او رفتار می‌کرد که حتی ماکسیم ماکسیمیچ را شگفت‌زده می‌کرد و برای مدتی، ناخدای پیر به خودش اجازه داد امیدوار باشد که افسر جوان بالاخره چیزی یافته که ارزش زیستن دارد."),
            StoryParagraph("But such hopes are always doomed when they concern a man like Pechorin, for whom possession inevitably breeds indifference, and affection inevitably curdles into contempt.", "اما چنین امیدهایی همیشه محکوم به شکست هستند وقتی به مردی مثل پچورین مربوط می‌شوند، که برایش مالکیت اجتناب‌ناپذیر بی‌تفاوتی می‌زاید و محبت اجتناب‌ناپذیر به تحقیر تبدیل می‌شود."),
            StoryParagraph("The change came gradually, as such changes always do, beginning with small absences and ending with long days spent hunting in the mountains, far from the woman who had given up everything for him.", "تغییر تدریجی آمد، همانطور که چنین تغییراتی همیشه می‌آیند، با غیبت‌های کوچک آغاز شد و به روزهای طولانی شکار در کوه‌ها ختم شد، دور از زنی که همه چیز را برایش فدا کرده بود."),
            StoryParagraph("Bela felt the change with the terrible sensitivity of the truly loving, and she grew quiet, and then sad, and then, at last, resigned.", "بلا تغییر را با حساسیت هولناک عاشق واقعی حس کرد و ساکت شد و بعد غمگین و در نهایت، تسلیم."),
            StoryParagraph("She did not complain, did not reproach, did not demand — she simply faded, like a flower deprived of sunlight, and Maxim Maximych watched her decline with a grief he could not express.", "شکایت نکرد، سرزنش نکرد، چیزی نخواست — او فقط محو شد، مثل گلی که از نور خورشید محروم شده و ماکسیم ماکسیمیچ زوالش را با اندوهی که نمی‌توانست بیان کند تماشا کرد."),
            StoryParagraph("The tragedy reached its climax one afternoon when Kazbich, the warrior whose horse had been stolen, appeared at the fort.", "تراژدی بعدازظهری به اوج رسید وقتی کازبیچ، جنگجویی که اسبش دزدیده شده بود، در قلعه ظاهر شد."),
            StoryParagraph("He had come to retrieve what was his, and finding Bela alone, he seized her and tried to escape with her on his horse.", "او آمده بود تا مال خودش را پس بگیرد و بلا را تنها یافت و او را گرفت و تلاش کرد با اسبش فرار کند."),
            StoryParagraph("Pechorin returned in time to pursue, and in the chase that followed, Kazbich, realizing that he could not escape with his captive, struck her down and fled.", "پچورین به موقع برای تعقیب برگشت و در تعقیبی که در پی آمد، کازبیچ چون فهمید نمی‌تواند با اسیرش فرار کند، او را زد و گریخت."),
            StoryParagraph("Bela died two days later, in Pechorin's arms, and her last words, according to Maxim Maximych, were words of love — love for the man who had destroyed her.", "بلا دو روز بعد در آغوش پچورین مرد و آخرین کلماتش، به گفته ماکسیم ماکسیمیچ، کلمات عشق بودند — عشق به مردی که نابودش کرده بود."),
            StoryParagraph("Pechorin, throughout her dying and her death, maintained an unbroken composure that Maxim Maximych found deeply unsettling.", "پچورین در طول بیماری و مرگش آرامشی بی‌وقفه حفظ کرد که ماکسیم ماکسیمیچ آن را عمیقاً نگران‌کننده یافت."),
            StoryParagraph("He did not weep, did not rail against fate, did not express any emotion whatsoever; he simply sat beside her, silent and still, as though he were observing the death of a stranger.", "گریه نکرد، علیه تقدیر فریاد نزد، هیچ احساسی بیان نکرد؛ فقط کنارش نشست، ساکت و بی‌حرکت، گویی مرگ یک غریبه را تماشا می‌کرد."),
            StoryParagraph("'There,' said Maxim Maximych, concluding his narrative, 'is the story of Bela. And that, my friend, is the kind of man Pechorin is.'", "ماکسیم ماکسیمیچ در پایان روایتش گفت: «این داستان بلاست. و آن، دوستم، همان نوع مردی است که پچورین است.»"),
            StoryParagraph("As the old captain fell silent, I found myself pondering the tale he had told, and the man it had revealed.", "وقتی ناخدای پیر ساکت شد، خودم را در حال اندیشیدن به داستانی یافتم که گفته بود و مردی که آشکار کرده بود."),
            StoryParagraph("Pechorin, I realized, was not a villain in the conventional sense, nor was he a victim; he was something more disturbing — a man who had been given every gift and had found them all worthless.", "فهمیدم پچورین شرور به معنای متعارف نبود و قربانی هم نبود؛ چیز نگران‌کننده‌تری بود — مردی که هر موهبتی به او داده شده و همه را بی‌ارزش یافته بود."),
            StoryParagraph("He was a man who had reached the end of every path and found them all leading to the same void, and who could no longer summon the energy to pretend otherwise.", "او مردی بود که به انتهای هر راهی رسیده و همه را به همان خلا کشانده یافته و دیگر نمی‌توانست انرژی جمع کند که خلافش را تظاهر کند."),
            StoryParagraph("The tale of Bela was, in a sense, the tale of Pechorin himself: the story of a beautiful thing destroyed by a man who could not love it.", "داستان بلا به نوعی داستان خود پچورین بود: داستان چیزی زیبا که توسط مردی نابود شده که نمی‌توانست دوستش داشته باشد."),
            StoryParagraph("And so ended the first part of my journey, in the wild mountains of the Caucasus, with the tale of a man who was a hero of his time precisely because he was so perfectly, so tragically representative of its spiritual condition.", "و اینگونه اولین بخش سفرم در کوه‌های وحشی قفقاز به پایان رسید، با داستان مردی که قهرمان زمانش بود دقیقاً چون نماینده‌ای چنین بی‌نقص و تراژیک از وضعیت روحی آن زمان بود.")
        )
    )

    // ─────────── فصل ۲: ماکسیم ماکسیمیچ ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Maxim Maximych", titlePersian = "ماکسیم ماکسیمیچ",
        paragraphs = listOf(
            StoryParagraph("After Bela's death, Pechorin departed from the fortress and accepted a transfer to another part of the Caucasus, and Maxim Maximych, whose attachment to the young officer had been genuine and profound, was left behind to grieve in solitude.", "بعد از مرگ بلا، پچورین قلعه را ترک کرد و انتقالی به بخش دیگری از قفقاز پذیرفت و ماکسیم ماکسیمیچ که دلبستگی‌اش به افسر جوان اصیل و عمیق بود، برای سوگواری در تنهایی رها شد."),
            StoryParagraph("The years passed, as years always do, indifferent to the grief and pleasure of those who mark their passage, and Maxim Maximych grew old in the service of an empire that had never asked his opinion on anything.", "سال‌ها گذشتند، همانطور که سال‌ها همیشه می‌گذرند، بی‌تفاوت به اندوه و لذت کسانی که عبورشان را نشانه می‌گذارند و ماکسیم ماکسیمیچ در خدمت امپراتوری‌ای پیر شد که هرگز نظرش را درباره هیچ چیز نپرسیده بود."),
            StoryParagraph("He had, however, never forgotten Pechorin, and whenever he spoke of him — which was often — his voice carried a note of baffled affection that revealed more than words could express.", "اما هرگز پچورین را فراموش نکرده بود و هر وقت از او صحبت می‌کرد — که اغلب بود — صدایش نُتی از محبت گیج به خود می‌گرفت که بیش از کلمات بیان می‌کرد."),
            StoryParagraph("He described Pechorin as the strangest man he had ever known, a man in whom the most brilliant qualities coexisted with the most profound deficiencies of character.", "او پچورین را عجیب‌ترین مردی توصیف می‌کرد که تا حالا شناخته، مردی که در او درخشان‌ترین ویژگی‌ها با عمیق‌ترین کاستی‌های شخصیت همزیستی داشتند."),
            StoryParagraph("'He could charm the birds from the trees,' the old captain would say, 'and then, once he had them, he would not know what to do with them.'", "ناخدای پیر می‌گفت: «او می‌توانست پرندگان را از درختان طلسم کند و بعد، وقتی صیدشان کرده بود، نمی‌دانست با آن‌ها چه کند.»"),
            StoryParagraph("It was several years after our first meeting that I encountered Maxim Maximych again, at a modest inn on one of the great roads that traversed the southern provinces.", "چند سال پس از اولین ملاقاتمان بود که دوباره با ماکسیم ماکسیمیچ برخورد کردم، در مسافرخانه‌ای ساده در یکی از راه‌های بزرگ که ولایات جنوبی را می‌پیمود."),
            StoryParagraph("He was older now, and the years had left their marks upon him with an honesty that was almost brutal, but his eyes still held that peculiar mixture of kindness and world-weariness that I remembered.", "او حالا پیرتر بود و سال‌ها آثار خود را با صداقتی تقریباً وحشیانه رویش گذاشته بودند، اما چشمانش هنوز آن آمیزه عجیب مهربانی و خستگی دنیوی را داشت که به یاد می‌آوردم."),
            StoryParagraph("We greeted each other with the warmth of old acquaintances, and as we sat together over a bottle of wine, he began once more to speak of Pechorin.", "با گرمای آشنایان قدیمی به هم سلام کردیم و همانطور که با هم کنار بطری شرابی نشستیم، دوباره شروع کرد به صحبت از پچورین."),
            StoryParagraph("It was then that a carriage pulled up to the inn, and a man descended who seemed, even at a distance, to command attention by some quality that was difficult to define.", "آن موقع بود که کالسکه‌ای جلوی مسافرخانه ایستاد و مردی پیاده شد که به نظر می‌رسید، حتی از دور، توجه را با کیفیتی که تعریفش دشوار بود جلب می‌کند."),
            StoryParagraph("He was tall and elegantly dressed, and he carried himself with that careless dignity that is the birthright of those who have never had to earn respect.", "او بلندقد و شیک‌پوش بود و با آن وقار بی‌خیالی راه می‌رفت که حق مادرزاد کسانی است که هرگز مجبور نبوده‌اند احترام به دست آورند."),
            StoryParagraph("Maxim Maximych's eyes widened with recognition, and he rose from his seat with an alacrity that belied his years.", "چشمان ماکسیم ماکسیمیچ از شناخت گشاد شد و از جای خود با چالاکی‌ای بلند شد که سال‌هایش را تکذیب می‌کرد."),
            StoryParagraph("'Pechorin!' he exclaimed, and there was in his voice a joy that was almost painful to hear.", "فریاد زد: «پچورین!» و در صدایش شادی‌ای بود که شنیدنش تقریباً دردناک بود."),
            StoryParagraph("The man turned, and for a moment, his face registered no emotion whatsoever, as though the name meant nothing to him.", "مرد برگشت و برای لحظه‌ای، صورتش هیچ احساسی نشان نداد، گویی آن نام برایش هیچ معنایی نداشت."),
            StoryParagraph("Then, with an effort that was almost imperceptible, he arranged his features into an expression of polite recognition, and he approached the old captain with his hand extended.", "بعد، با تلاشی که تقریباً نامحسوس بود، چهره‌اش را به حالتی از شناخت مؤدبانه آراست و با دست دراز به سمت ناخدای پیر آمد."),
            StoryParagraph("But the warmth that animated Maxim Maximych was not returned; Pechorin was correct, distant, and utterly without affection, as though the years they had spent together had been erased from his memory.", "اما گرمایی که ماکسیم ماکسیمیچ را زنده می‌کرد برگردانده نشد؛ پچورین درست، دور و کاملاً بی‌محبت بود، گویی سال‌هایی که با هم گذرانده بودند از حافظه‌اش پاک شده بود."),
            StoryParagraph("The old captain, visibly wounded, tried to remind him of the past, to summon some echo of the friendship that had once existed between them.", "ناخدای پیر که آشکارا زخمی شده بود، تلاش کرد گذشته را به یادش آورد، پژواکی از دوستی‌ای که زمانی میانشان وجود داشت را فرا خواند."),
            StoryParagraph("But Pechorin remained impassive, responding to every allusion with a politeness that was more insulting than any rudeness could have been.", "اما پچورین بی‌احساس ماند و به هر اشاره‌ای با ادبی پاسخ داد که از هر بی‌ادبی‌ای توهین‌آمیزتر بود."),
            StoryParagraph("'I am on my way to Persia,' he said at last, 'and I doubt that I shall ever return to these regions.'", "بالاخره گفت: «در راه ایران هستم و شک دارم هرگز به این نواحی برگردم.»"),
            StoryParagraph("Maxim Maximych asked if he had any papers that he wished him to keep, and Pechorin, with the air of a man disposing of an inconvenience, handed him a packet of his journals.", "ماکسیم ماکسیمیچ پرسید آیا کاغذهایی دارد که می‌خواهد او نگه دارد و پچورین با حالتی از مردی که از یک ناراحتی خلاص می‌شود، بسته‌ای از دفترهای خاطراتش را به او داد."),
            StoryParagraph("'Do with them as you please,' he said. 'They are of no further interest to me.'", "گفت: «هر چه می‌خواهی با آن‌ها بکن. دیگر برایم جالب نیستند.»"),
            StoryParagraph("Then he bowed, coldly and formally, and returned to his carriage, and within moments, he was gone.", "بعد سرد و رسمی تعظیم کرد و به کالسکه‌اش برگشت و در عرض چند لحظه، رفته بود."),
            StoryParagraph("Maxim Maximych stood motionless in the road, staring after the departing carriage, and I saw, in his weathered face, a sorrow that was almost unbearable to witness.", "ماکسیم ماکسیمیچ بی‌حرکت در جاده ایستاد و به کالسکه در حال دور شدن خیره شد و در صورت هوازده‌اش اندوهی دیدم که شاهد بودنش تقریباً غیرقابل تحمل بود."),
            StoryParagraph("'That,' he said at last, in a voice that trembled with suppressed emotion, 'is the way he treats everyone who has ever loved him.'", "بالاخره با صدایی که از احساس سرکوب‌شده می‌لرزید گفت: «این روش او با هر کسی است که تا حالا دوستش داشته.»"),
            StoryParagraph("He handed me the packet of journals, saying that I might find in them some explanation of the mystery that Pechorin represented.", "او بسته دفترها را به من داد و گفت شاید در آن‌ها توضیحی برای معمایی که پچورین نمایندگی می‌کرد پیدا کنم."),
            StoryParagraph("'Perhaps,' he said, 'you will understand him better than I ever could.'", "گفت: «شاید تو او را بهتر از من که هرگز نتوانستم بفهممش، بفهمی.»"),
            StoryParagraph("That night, as I began to read Pechorin's journals, I entered into a mind that was at once brilliant and tormented, a consciousness that observed the world with unflinching clarity and found it wanting.", "آن شب، وقتی شروع کردم به خواندن دفترهای پچورین، به ذهنی وارد شدم که همزمان درخشان و شکنجه‌شده بود، آگاهی‌ای که دنیا را با شفافیتی بی‌لرزش مشاهده می‌کرد و آن را ناقص می‌یافت."),
            StoryParagraph("The journals were divided into several distinct narratives, each illuminating a different aspect of their author's complex and contradictory character.", "دفترها به چند روایت متمایز تقسیم شده بودند که هر یک جنبه متفاوتی از شخصیت پیچیده و متناقض نویسنده‌شان را روشن می‌کرد."),
            StoryParagraph("The first, entitled 'Taman', recounted a strange and unsettling adventure on the Black Sea coast.", "اولی، با عنوان «تمن»، ماجراجویی عجیب و نگران‌کننده‌ای در ساحل دریای سیاه را بازگو می‌کرد."),
            StoryParagraph("The second, entitled 'Princess Mary', described a complex game of love and jealousy played out at a fashionable spa in the Caucasus.", "دومی، با عنوان «شاهزاده خانم مری»، بازی پیچیده‌ای از عشق و حسادت را که در آبگرم شیکی در قفقاز اجرا شده بود توصیف می‌کرد."),
            StoryParagraph("The third, entitled 'The Fatalist', recounted an evening of philosophical debate and mortal danger that had tested Pechorin's deepest beliefs.", "سومی، با عنوان «فاتالیست»، شبی از بحث فلسفی و خطر مرگباری را بازگو می‌کرد که عمیق‌ترین باورهای پچورین را آزموده بود."),
            StoryParagraph("As I read these narratives, I began to construct, from the fragments they provided, a portrait of a man who was both a product and a victim of his age.", "همانطور که این روایت‌ها را می‌خواندم، شروع کردم به ساختن، از تکه‌هایی که فراهم می‌کردند، پرتره‌ای از مردی که هم محصول عصرش بود و هم قربانی آن."),
            StoryParagraph("He was a man who had inherited the skepticism of one generation and the ambition of another, and who had found himself unable to commit to either.", "او مردی بود که شک‌گرایی یک نسل و جاه‌طلبی نسل دیگری را به ارث برده بود و خودش را قادر به تعهد به هیچ‌کدام نیافته بود."),
            StoryParagraph("He was a man who had been taught to value reason above all else, and who had discovered that reason, without faith, leads only to despair.", "او مردی بود که یاد گرفته بود عقل را بیش از هر چیز ارزش بگذارد و کشف کرده بود که عقل، بدون ایمان، تنها به ناامیدی می‌رسد."),
            StoryParagraph("He was a man who had been given the power to see through every illusion, and who had found, on the other side of illusion, only emptiness.", "او مردی بود که قدرت دیدن از میان هر توهمی به او داده شده بود و در طرف دیگر توهم، تنها پوچی یافته بود."),
            StoryParagraph("And this, I came to understand, was the tragedy of Pechorin, and the tragedy of his generation: to be too intelligent to believe in anything, and too sensitive to live without belief.", "و این، فهمیدم، تراژدی پچورین بود و تراژدی نسل او: بسیار باهوش بودن برای باور به هر چیزی و بسیار حساس بودن برای زندگی بدون باور."),
            StoryParagraph("The journals of Pechorin were, in the end, the spiritual autobiography of an entire era, an era that had lost its old gods without finding new ones.", "دفترهای پچورین در نهایت زندگینامه روحی تمام یک عصر بودند، عصری که خدایان قدیمی‌اش را از دست داده بود بی‌آنکه خدایان جدیدی بیابد."),
            StoryParagraph("And so ended the second part of my journey, in the company of an old soldier and the ghost of a man he could not forget.", "و اینگونه بخش دوم سفرم به پایان رسید، در همراهی سربازی پیر و شبح مردی که نمی‌توانست فراموشش کند.")
        )
    )

    // ─────────── فصل ۳: تمن ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Taman", titlePersian = "تمن",
        paragraphs = listOf(
            StoryParagraph("Taman, Pechorin wrote, is the most wretched town in all of Russia, and I am inclined to believe him, having passed through places that would have made even the most stoic traveler weep with despair.", "پچورین نوشت که تمن رقت‌انگیزترین شهر تمام روسیه است و من مایلم او را باور کنم، چرا که از مکان‌هایی گذشته‌ام که حتی صبورترین مسافر را نیز از ناامیدی به گریه می‌اندازند."),
            StoryParagraph("It was there, on a dark night in autumn, that Pechorin, traveling by post-chaise, arrived at an inn whose accommodations could only generously be described as rudimentary.", "آنجا بود، در شبی تاریک از پاییز، که پچورین، در حال سفر با کالسکه پست، به مسافرخانه‌ای رسید که تسهیلاتش را تنها می‌شد سخاوتمندانه ابتدایی توصیف کرد."),
            StoryParagraph("The town itself was little more than a cluster of huts huddled against the sea, and the inhabitants, who seemed to be of a peculiar and suspicious character, regarded the arrival of a Russian officer with evident unease.", "خود شهر چیزی بیشتر از مجموعه‌ای از کلبه‌های چسبیده به دریا نبود و ساکنانش که به نظر می‌رسید شخصیتی عجیب و مشکوک داشتند، رسیدن افسری روسی را با ناآرامی آشکاری نگریستند."),
            StoryParagraph("Pechorin was assigned a room in a hut belonging to an old deaf woman, and as he lay on his bed attempting to sleep, he became aware of strange sounds coming from the shore.", "به پچورین اتاقی در کلبه‌ای متعلق به پیرزنی ناشنوا اختصاص داده شد و همانطور که روی تختش دراز کشیده بود و تلاش می‌کرد بخوابد، از صداهای عجیبی که از ساحل می‌آمد آگاه شد."),
            StoryParagraph("A young girl was standing by the water, singing a strange and haunting melody, and her voice carried across the darkness with an eerie sweetness that seemed to promise both pleasure and danger.", "دختری جوان کنار آب ایستاده بود و آهنگی عجیب و شبح‌وار می‌خواند و صدایش در تاریکی با شیرینی شبح‌آسایی پیچید که به نظر می‌رسید هم لذت و هم خطر را وعده می‌داد."),
            StoryParagraph("The song was in a language he did not understand, but its melody was universal — the melody of longing, of restlessness, of a heart that could not find peace.", "آهنگ به زبانی بود که نمی‌فهمید، اما ملودی‌اش جهانی بود — ملودی اشتیاق، بی‌قراری، قلبی که نمی‌توانست آرامش بیابد."),
            StoryParagraph("The next day, Pechorin made the acquaintance of this girl, who was, it transpired, the daughter of the deaf woman and the sister of a young smuggler who used the hut as a base for his illicit operations.", "روز بعد، پچورین با این دختر آشنا شد که معلوم شد دختر آن زن ناشنوا و خواهر قاچاقچی جوانی بود که از کلبه به‌عنوان پایگاهی برای عملیات غیرقانونی‌اش استفاده می‌کرد."),
            StoryParagraph("She was beautiful in a way that was almost feral, with wild dark eyes and a laugh that seemed to mock the very idea of safety, and Pechorin, whose instinct for danger was matched only by his inability to resist it, found himself drawn to her.", "او به شکلی تقریباً وحشی زیبا بود، با چشمانی تیره و وحشی و خنده‌ای که به نظر می‌رسید خود ایده امنیت را مسخره می‌کرد و پچورین که غریزه‌اش برای خطر فقط با ناتوانی‌اش از مقاومت در برابر آن برابری می‌کرد، به سمتش کشیده شد."),
            StoryParagraph("They spent the day together, speaking in riddles and half-truths, and Pechorin, who prided himself on his ability to read others, found himself unable to determine whether she was a simple girl or a calculating conspirator.", "آن‌ها روز را با هم گذراندند، با معما و نیمه‌حقیقت صحبت کردند و پچورین که به توانایی‌اش در خواندن دیگران می‌بالید، خودش را قادر به تشخیص اینکه او دختری ساده است یا همدستِ محاسبه‌گر ندید."),
            StoryParagraph("That night, she summoned him to the shore, and in a small boat, they rowed out into the darkness, away from the lights of the town and into the mystery that she represented.", "آن شب، او را به ساحل فرا خواند و در قایقی کوچک، به تاریکی پارو زدند، دور از نورهای شهر و به سمت معمایی که او نمایندگی می‌کرد."),
            StoryParagraph("But the boat was not what it seemed; beneath the seat where Pechorin sat were concealed the goods that her brother intended to smuggle, and her purpose in bringing him out was not romantic but mercenary.", "اما قایق آن چیزی نبود که به نظر می‌رسید؛ زیر صندلی که پچورین رویش نشسته بود کالاهایی پنهان بود که برادرش قصد قاچاقشان را داشت و هدفش از بردنش به دریا رمانتیک نبود، بلکه پول‌محور بود."),
            StoryParagraph("When Pechorin discovered the truth, a struggle ensued, and in the course of that struggle, the girl, with a strength that belied her slender form, attempted to push him overboard into the cold, dark water.", "وقتی پچورین حقیقت را کشف کرد، تقلایی درگرفت و در جریان آن تقلا، دختر با قدرتی که با اندام باریکش ناهمخوان بود، تلاش کرد او را به آب سرد و تاریک بیندازد."),
            StoryParagraph("Pechorin, who had survived too many dangers to be killed by a smuggler's sister, managed to overpower her, and he threw her into the sea, where she was rescued by her brother, who had followed in another boat.", "پچورین که از خطرات بیش از حد جان به‌در برده بود که به دست خواهر قاچاقچی‌ای کشته شود، موفق شد مغلوبش کند و او را به دریا انداخت، جایی که برادرش که در قایقی دیگر دنبال کرده بود نجاتش داد."),
            StoryParagraph("The next morning, Pechorin's belongings had been stolen, and the girl and her brother had vanished, leaving behind only the old deaf woman and the memory of an adventure that had been as meaningless as it was dangerous.", "صبح روز بعد، وسایل پچورین دزدیده شده بودند و دختر و برادرش ناپدید شده بودند و تنها پیرزن ناشنوا و خاطره ماجراجویی‌ای که به همان اندازه بی‌معنا که خطرناک بود رها کرده بودند."),
            StoryParagraph("Pechorin left Taman that same day, and in his journal, he recorded his reflections on the episode with characteristic honesty.", "پچورین همان روز تمن را ترک کرد و در دفترش، تأملاتش را درباره این ماجرا با صداقت مشخصه‌اش ثبت کرد."),
            StoryParagraph("'I felt annoyed with myself,' he wrote, 'for having allowed myself to be deceived by a mere girl. But such is life: everything ends in disappointment, and the only constant is the emptiness that follows.'", "او نوشت: «از خودم آزرده شدم که اجازه داده بودم دختری صرفاً فریبم دهد. اما زندگی همین است: همه چیز به ناامیدی ختم می‌شود و تنها ثابت، پوچی‌ای است که در پی می‌آید.»"),
            StoryParagraph("'Yet I cannot regret the episode,' he continued, 'for it gave me, for a few hours, the illusion of feeling something — even if that something was only the thrill of danger.'", "ادامه داد: «با این حال نمی‌توانم از این ماجرا پشیمان باشم، چون برای چند ساعت توهم احساس چیزی را به من داد — حتی اگر آن چیز فقط هیجان خطر بود.»"),
            StoryParagraph("The episode at Taman was, in its way, a microcosm of Pechorin's entire existence: a brief encounter, an intense experience, and a final emptiness that nothing could fill.", "ماجرای تمن به شیوه خودش، جهان کوچکی از کل وجود پچورین بود: برخوردی کوتاه، تجربه‌ای شدید و پوچی نهایی‌ای که هیچ چیز نمی‌توانست پرش کند."),
            StoryParagraph("He was a man who could not help but seek out intensity, because only intensity could momentarily distract him from the void within, but who found, in the aftermath of every intense experience, that the void had grown only deeper.", "او مردی بود که نمی‌توانست از جستجوی شدت خودداری کند، چون تنها شدت می‌توانست لحظه‌ای از پوچی درونش منحرفش کند، اما در پس‌آیند هر تجربه شدید، پوچی را عمیق‌تر می‌یافت."),
            StoryParagraph("And so he continued to travel, from one adventure to another, from one woman to another, from one danger to another, always seeking something he could not name and never finding it.", "و اینگونه به سفر ادامه داد، از ماجراجویی به ماجراجویی، از زنی به زن دیگر، از خطری به خطر دیگر، همیشه دنبال چیزی می‌گشت که نمی‌توانست نامش را ببرد و هرگز نمی‌یافتش."),
            StoryParagraph("That was the story of Taman, a story of smugglers and shadows and the restless heart of a man who could not find peace.", "این داستان تمن بود، داستانی از قاچاقچیان و سایه‌ها و قلب بی‌قرار مردی که نمی‌توانست آرامش پیدا کند."),
            StoryParagraph("And it was, in its essence, a story that would repeat itself, in various forms, throughout the remainder of Pechorin's life.", "و در جوهرش، داستانی بود که در طول باقی عمر پچورین، به اشکال مختلف، خودش را تکرار می‌کرد.")
        )
    )

    // ─────────── فصل ۴: شاهزاده خانم مری ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Princess Mary", titlePersian = "شاهزاده خانم مری",
        paragraphs = listOf(
            StoryParagraph("The longest and most complex of Pechorin's narratives concerns his stay at the spa town of Pyatigorsk, where the mineral waters of the Caucasus drew the fashionable and the idle from every corner of the empire.", "طولانی‌ترین و پیچیده‌ترین روایت پچورین مربوط به اقامتش در شهر آبگرم پیاتیگورسک است، جایی که آب‌های معدنی قفقاز شیک‌پوشان و بیکاران را از هر گوشه امپراتوری جذب می‌کرد."),
            StoryParagraph("It was a world of surfaces, of appearances cultivated for the benefit of other appearances, of conversations that said nothing and gestures that meant less.", "دنیایی از سطوح بود، از ظواهری که برای فایده ظواهر دیگر پرورش می‌یافتند، از گفتگوهایی که هیچ نمی‌گفتند و اشاره‌هایی که معنای کمتری داشتند."),
            StoryParagraph("At the center of this artificial world stood a young princess named Mary, whose beauty and innocence had made her the object of universal admiration.", "در مرکز این دنیای مصنوعی، شاهزاده خانم جوانی به نام مری ایستاده بود که زیبایی و معصومیتش او را موضوع تحسین جهانی کرده بود."),
            StoryParagraph("She was, Pechorin observed with his customary detachment, exactly the sort of woman that young officers were expected to fall in love with: beautiful, virtuous, and utterly without the resources to resist a determined seducer.", "پچورین با جداافتادگی معمولش مشاهده کرد که او دقیقاً همان نوع زنی بود که انتظار می‌رفت افسران جوان عاشقش شوند: زیبا، با فضیلت و کاملاً بدون منابع مقاومت در برابر فریبنده‌ای مصمم."),
            StoryParagraph("Pechorin, who had no genuine interest in the princess whatsoever, decided to pursue her nevertheless, not because he desired her, but because he was bored and because another man desired her too.", "پچورین که اصلاً علاقه واقعی به شاهزاده خانم نداشت، به هر حال تصمیم گرفت دنبالش برود، نه چون می‌خواستش، بلکه چون حوصله‌اش سر رفته بود و چون مرد دیگری هم می‌خواستش."),
            StoryParagraph("That other man was Grushnitsky, a young officer of limited intelligence and unlimited vanity, whose one ambition was to appear more significant than he was.", "آن مرد دیگر گروشنیتسکی بود، افسر جوانی با هوش محدود و خودبینی بی‌حد که تنها جاه‌طلبی‌اش این بود که مهم‌تر از آنچه هست به نظر برسد."),
            StoryParagraph("Grushnitsky had already declared himself the princess's devoted admirer, and Pechorin, with the casual cruelty of a man who could not resist manipulating those around him, decided to demonstrate how easily such an admirer could be supplanted.", "گروشنیتسکی قبلاً خودش را ستایشگر فداکار شاهزاده خانم اعلام کرده بود و پچورین با خشونت بی‌خیال مردی که نمی‌توانست در برابر دستکاری اطرافیانش مقاومت کند، تصمیم گرفت نشان دهد چنین ستایشگری چقدر راحت می‌تواند جایگزین شود."),
            StoryParagraph("His campaign was a masterpiece of psychological manipulation, conducted with a precision that would have been admirable had it not been so utterly without moral justification.", "کمپینش شاهکاری از دستکاری روانشناختی بود که با دقتی اجرا شد که تحسین‌برانگیز می‌بود اگر کاملاً بدون توجیه اخلاقی نبود."),
            StoryParagraph("He ignored the princess completely, knowing that indifference is more attractive than attention, and he waited for her curiosity to overcome her pride.", "او شاهزاده خانم را کاملاً نادیده گرفت، چون می‌دانست بی‌تفاوتی جذاب‌تر از توجه است و منتظر ماند تا کنجکاوی‌اش غرورش را مغلوب کند."),
            StoryParagraph("He cultivated the friendship of the princess's mother, knowing that maternal approval would lower the daughter's defenses.", "او دوستی مادر شاهزاده خانم را پرورد، چون می‌دانست تأیید مادرانه دفاع‌های دختر را کاهش می‌دهد."),
            StoryParagraph("He engineered encounters that seemed accidental, knowing that the appearance of fate is more seductive than the reality of intention.", "او برخوردهایی ترتیب داد که تصادفی به نظر می‌رسیدند، چون می‌دانست ظاهر تقدیر از واقعیت نیت فریبنده‌تر است."),
            StoryParagraph("And slowly, inevitably, Mary began to fall in love with him, as so many women had fallen before, and as so many would fall after.", "و به‌آرامی، اجتناب‌ناپذیر، مری شروع کرد به عشق ورزیدن به او، همانطور که بسیاری زنان پیش از این عاشق شده بودند و همانطور که بسیاری بعد از این عاشق می‌شدند."),
            StoryParagraph("Meanwhile, in the background of this emotional drama, another narrative was unfolding: Pechorin had renewed his acquaintance with Vera, a woman he had loved years before and had never entirely forgotten.", "در همین حال، در پس‌زمینه این درام احساسی، روایت دیگری در جریان بود: پچورین آشنایی‌اش را با ورا تجدید کرده بود، زنی که سال‌ها پیش دوستش داشته و هرگز کاملاً فراموشش نکرده بود."),
            StoryParagraph("Vera was now married to another man, a man whose wealth and position had made him an acceptable match, but her heart still belonged to Pechorin, and their reunion was as passionate as it was doomed.", "ورا حالا با مرد دیگری ازدواج کرده بود، مردی که ثروت و جایگاهش او را همسری قابل قبول کرده بود، اما قلبش هنوز به پچورین تعلق داشت و دیدار دوباره‌شان به همان اندازه که شورانگیز بود، محکوم به شکست هم بود."),
            StoryParagraph("The contrast between these two relationships — the one with Vera, which was genuine but impossible, and the one with Mary, which was possible but false — was the engine that drove the entire drama toward its catastrophic conclusion.", "تضاد میان این دو رابطه — آن یکی با ورا که اصیل اما ناممکن بود و این یکی با مری که ممکن اما دروغین بود — موتوری بود که کل درام را به سوی نتیجه فاجعه‌بارش می‌راند."),
            StoryParagraph("Pechorin, torn between a love he could not have and a love he did not want, found himself in a position that was, for a man of his character, almost unbearable.", "پچورین که میان عشقی که نمی‌توانست داشته باشد و عشقی که نمی‌خواست پاره شده بود، خودش را در موقعیتی یافت که برای مردی با شخصیت او تقریباً غیرقابل تحمل بود."),
            StoryParagraph("He could not bring himself to break with Vera, whose very unavailability made her precious, and he could not bring himself to spare Mary, whose very availability made her contemptible.", "او نمی‌توانست با ورا قطع کند، که دست‌نیازی‌اش او را ارزشمند می‌کرد و نمی‌توانست به مری رحم کند، که در دسترس بودنش او را حقیر می‌کرد."),
            StoryParagraph("And so he continued the game with both, deceiving each in a different way, and hating himself for the deception even as he continued to practice it.", "و اینگونه بازی را با هر دو ادامه داد، هر یک را به شکلی متفاوت فریب داد و خودش را به خاطر فریب در همان حال که به اجرایش ادامه می‌داد، متنفر بود."),
            StoryParagraph("The climax came, as such climaxes always do, in a duel — that archaic ceremony of honor that Pechorin despised even as he participated in it.", "اوج، همانطور که چنین اوج‌هایی همیشه می‌آیند، در دوئلی فرا رسید — آن مراسم کهنِ افتخاری که پچورین حتی وقتی در آن شرکت می‌کرد تحقیرش می‌کرد."),
            StoryParagraph("Grushnitsky, driven to desperation by jealousy and humiliation, challenged Pechorin to a duel, and Pechorin accepted with a calm that was more terrible than any rage.", "گروشنیتسکی که توسط حسادت و تحقیر به ناامیدی رانده شده بود، پچورین را به دوئل دعوت کرد و پچورین با آرامشی که از هر خشمی هولناک‌تر بود پذیرفت."),
            StoryParagraph("The duel was fought on a rocky ledge above a precipice, and as the two men stood facing each other, the sun rising behind them, Pechorin experienced a moment of strange clarity.", "دوئل روی صخره‌ای بالای پرتگاه انجام شد و همانطور که دو مرد روبروی هم ایستادند و خورشید پشت سرشان طلوع می‌کرد، پچورین لحظه‌ای از وضوح عجیب را تجربه کرد."),
            StoryParagraph("He realized, in that moment, that he did not hate Grushnitsky, and did not even despise him; he simply did not care about him at all, and this indifference seemed to him more damning than any hatred could be.", "در آن لحظه دریافت که از گروشنیتسکی متنفر نیست و حتی تحقیرش هم نمی‌کند؛ فقط اصلاً برایش مهم نبود و این بی‌تفاوتی به نظرش از هر نفرتی محکوم‌کننده‌تر بود."),
            StoryParagraph("The duel proceeded according to its terrible ritual, and when it was over, Grushnitsky lay dead, and Pechorin stood over him with an expression that was impossible to read.", "دوئل طبق آیین هولناکش پیش رفت و وقتی تمام شد، گروشنیتسکی مرده بود و پچورین با حالتی که خواندنش ناممکن بود بالای سرش ایستاد."),
            StoryParagraph("He did not feel triumph, or guilt, or grief; he felt only the vast emptiness that had become his constant companion.", "پیروزی، گناه یا اندوه حس نکرد؛ فقط پوچی عظیمی را حس کرد که همراه دائمی‌اش شده بود."),
            StoryParagraph("That evening, he received a letter from Vera, telling him that she was leaving, and that she would never see him again.", "آن عصر، نامه‌ای از ورا دریافت کرد که به او می‌گفت می‌رود و هرگز دوباره نمی‌بیندش."),
            StoryParagraph("He rode after her carriage, desperate to catch one last glimpse of her, but he could not overtake it, and when his horse collapsed beneath him, he was left alone on the empty road.", "او به دنبال کالسکه‌اش تاخت، ناامیدانه برای یک نگاه آخر، اما نتوانست برسد و وقتی اسبش زیرش فرو افتاد، در جاده خالی تنها ماند."),
            StoryParagraph("'I wept,' he wrote in his journal, 'but not for Vera. I wept because I realized, in that moment, that I was incapable of genuine feeling.'", "او در دفترش نوشت: «گریستم، اما نه برای ورا. گریستم چون در آن لحظه فهمیدم که قادر به احساس اصیل نیستم.»"),
            StoryParagraph("'I have spent my whole life searching for a feeling that I could not feel, a love that I could not love, a life that I could not live.'", "«تمام عمرم را صرف جستجوی احساسی کرده‌ام که نمی‌توانستم حس کنم، عشقی که نمی‌توانستم عشق بورزم، زندگی‌ای که نمی‌توانستم زندگی کنم.»"),
            StoryParagraph("And so ended the story of Princess Mary, the longest and most painful of Pechorin's narratives, the story of a man who could manipulate every emotion in others but could not feel any in himself.", "و اینگونه داستان شاهزاده خانم مری به پایان رسید، طولانی‌ترین و دردناک‌ترین روایت پچورین، داستان مردی که می‌توانست هر احساسی را در دیگران دستکاری کند اما نمی‌توانست هیچ‌کدام را در خودش حس کند."),
            StoryParagraph("The princess, Pechorin recorded in one of his final entries, was, as he had always intended, left heartbroken and disillusioned, and she would no doubt eventually recover, marry someone else, and live a life of comfortable mediocrity.", "پچورین در یکی از یادداشت‌های نهایی‌اش ثبت کرد که شاهزاده خانم، همانطور که همیشه قصد کرده بود، دل‌شکسته و سرخورده رها شد و بدون شک در نهایت بهبود می‌یابد، با کس دیگری ازدواج می‌کند و زندگی متوسط راحتی می‌کند."),
            StoryParagraph("But he, Pechorin, would not recover; he would continue to drift from one meaningless experience to another, until the accumulated weight of his own emptiness finally crushed him.", "اما او، پچورین، بهبود نمی‌یافت؛ به رانده شدن از یک تجربه بی‌معنا به تجربه‌ای دیگر ادامه می‌داد، تا وقتی وزن انباشته پوچی خودش او را در نهایت خرد کند."),
            StoryParagraph("That was the fate that awaited him, and he knew it, and there was nothing he could do to prevent it.", "این سرنوشتی بود که در انتظارش بود و می‌دانست و هیچ کاری نمی‌توانست برای جلوگیری از آن بکند.")
        )
    )

    // ─────────── فصل ۵: فاتالیست ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Fatalist", titlePersian = "فاتالیست",
        paragraphs = listOf(
            StoryParagraph("The final narrative in Pechorin's journals takes place at a Cossack garrison on the frontier, where the young officer was stationed after leaving the spa town.", "آخرین روایت در دفترهای پچورین در پادگان قزاق‌ها در مرز رخ می‌دهد، جایی که آن افسر جوان پس از ترک شهر آبگرم مستقر شده بود."),
            StoryParagraph("It was a place where boredom was the constant companion of every man, and where the officers filled the endless hours with cards, wine, and philosophical debate.", "جایی بود که کسالت همراه دائمی هر مردی بود و افسران ساعات بی‌پایان را با ورق، شراب و بحث فلسفی پر می‌کردند."),
            StoryParagraph("Among the officers was a young lieutenant named Vulich, a Serb whose courage was as famous as his eccentricity, and who held a belief that set him apart from his fellows: he was a fatalist.", "در میان افسران، ستوان جوانی به نام وولیچ بود، صربستانی که شجاعتش به همان اندازه غرابتش معروف بود و باوری داشت که او را از همنوعانش متمایز می‌کرد: او فاتالیست بود."),
            StoryParagraph("Vulich believed that the hour of every man's death was predetermined, and that no human effort could change it; he believed that the bullet that would kill a man was already marked with his name.", "وولیچ باور داشت ساعت مرگ هر انسان از پیش تعیین شده و هیچ تلاش انسانی نمی‌تواند تغییرش دهد؛ باور داشت گلوله‌ای که انسان را می‌کشد از قبل با نامش نشان شده است."),
            StoryParagraph("Pechorin, who believed in nothing, found such fatalism absurd, and he challenged Vulich to prove his belief with a demonstration that would have terrified any sane man.", "پچورین که به هیچ چیز باور نداشت، چنین فاتالیسمی را پوچ یافت و وولیچ را به چالش کشید که باوری که هر مرد عاقلی را به وحشت می‌انداخت، نمایش دهد."),
            StoryParagraph("Vulich, taking a pistol from the wall, proposed a simple experiment: he would hold the pistol to his own head, and Pechorin would say whether the weapon was loaded.", "وولیچ در حالی که تپانچه‌ای از دیوار برمی‌داشت، آزمایشی ساده پیشنهاد داد: تپانچه را به سر خودش می‌گذاشت و پچورین می‌گفت آیا سلاح پر است یا نه."),
            StoryParagraph("Pechorin, examining the pistol, could not determine whether it was loaded, and he said so; Vulich, smiling, announced that he would discover the truth by pulling the trigger.", "پچورین در حالی که تپانچه را بررسی می‌کرد، نمی‌توانست تشخیص دهد پر است یا نه و این را گفت؛ وولیچ با لبخندی اعلام کرد که با کشیدن ماشه حقیقت را کشف می‌کند."),
            StoryParagraph("The room fell silent as Vulich raised the pistol, and every man present felt the weight of the moment, that terrible suspended instant when life and death hang in perfect balance.", "اتاق ساکت شد همانطور که وولیچ تپانچه را بالا برد و هر مرد حاضر وزن آن لحظه را حس کرد، آن لحظه معلق و هولناک که زندگی و مرگ در تعادل کامل آویزانند."),
            StoryParagraph("Vulich pulled the trigger, and there was a click, and nothing more.", "وولیچ ماشه را کشید و صدای تقی بود و نه بیشتر."),
            StoryParagraph("The officers exhaled with relief, and Vulich, with a triumph that was not entirely convincing, announced that fate had spared him, proving his thesis that his hour had not yet come.", "افسران از آسودگی نفس کشیدند و وولیچ با پیروزی‌ای که کاملاً قانع‌کننده نبود اعلام کرد تقدیر او را بخشیده و تز او را ثابت کرده که ساعتش هنوز نرسیده."),
            StoryParagraph("But Pechorin, examining the pistol more closely, noticed that the hammer had struck but had failed to ignite the powder; the pistol, in other words, had not been loaded after all, and the demonstration had proven nothing.", "اما پچورین در حالی که تپانچه را دقیق‌تر بررسی می‌کرد، متوجه شد که چکش ضربه زده اما باروت را مشتعل نکرده؛ به عبارت دیگر، تپانچه پر نبوده و نمایش هیچ چیزی را ثابت نکرده بود."),
            StoryParagraph("When he pointed this out, Vulich, rather than admitting defeat, seized the pistol and fired it at a mark on the wall, and the bullet struck the mark perfectly, proving that the weapon had indeed been loaded.", "وقتی این را خاطرنشان کرد، وولیچ به جای اعتراف به شکست، تپانچه را گرفت و به سمت نشانه‌ای روی دیوار شلیک کرد و گلوله دقیقاً به نشانه خورد و ثابت کرد سلاح در واقع پر بوده است."),
            StoryParagraph("The officers were astounded, and Pechorin himself was forced to admit that the demonstration, while inconclusive, had been at the very least provocative.", "افسران حیرت‌زده شدند و خود پچورین مجبور شد بپذیرد که نمایش، هرچند نامعلوم، حداقل تحریک‌آمیز بوده است."),
            StoryParagraph("'You will see,' Vulich said, 'that the hour of my death is written, and that I will not die until that hour arrives.'", "وولیچ گفت: «خواهی دید که ساعت مرگم نوشته شده و تا آن ساعت نرسد نمی‌میرم.»"),
            StoryParagraph("Pechorin, unconvinced but intrigued, went home to his quarters and lay awake for hours, thinking about the mysterious intersection of fate and free will.", "پچورین که قانع نشده اما مجذوب شده بود، به اقامتگاهش رفت و ساعت‌ها بیدار دراز کشید و به تلاقی مرموز تقدیر و اختیار فکر کرد."),
            StoryParagraph("As he was returning to his quarters late that night, he encountered Vulich again, drunk and wandering through the dark streets.", "وقتی دیر آن شب به اقامتگاهش برمی‌گشت، دوباره با وولیچ روبرو شد، مست و در خیابان‌های تاریک سرگردان."),
            StoryParagraph("Vulich greeted him with the boisterous warmth of the intoxicated, and he began to speak of fate once more, declaring that he would prove his belief on the morrow.", "وولیچ با گرمای پرجنب‌وجوش مستان سلامش کرد و شروع کرد به صحبت دوباره از تقدیر و اعلام کرد که فردا باورش را ثابت می‌کند."),
            StoryParagraph("But he did not live to see the morrow; within minutes, a drunken Cossack attacked him with a sword, and Vulich died in the street without having fired a single shot in his own defense.", "اما زنده نماند که فردا را ببیند؛ در عرض چند دقیقه، قزاق مستی با شمشیر به او حمله کرد و وولیچ بدون آنکه یک گلوله به دفاع از خود شلیک کند در خیابان مرد."),
            StoryParagraph("Pechorin, who had witnessed the attack from a distance, stood over the body and thought about the irony of what had happened.", "پچورین که حمله را از دور شاهد بود، بالای جسد ایستاد و به طعنه آنچه اتفاق افتاده بود فکر کرد."),
            StoryParagraph("Vulich had believed that his hour was written, and he had been right, but not in the way he had intended; the hour had come precisely when he had least expected it, proving nothing except the impossibility of prediction.", "وولیچ باور داشت ساعتش نوشته شده و حق داشت، اما نه به شکلی که قصد کرده بود؛ ساعت دقیقاً زمانی که کمترین انتظارش را داشت فرا رسیده بود و چیزی جز ناممکنی پیش‌بینی را ثابت نکرده بود."),
            StoryParagraph("The death of Vulich, which should have been a vindication of fatalism, had become instead a refutation of it; and yet Pechorin, who did not believe in fate, found himself unable to explain what had happened.", "مرگ وولیچ که می‌بایست تأییدی بر فاتالیسم باشد، در عوض تکذیبی بر آن شده بود؛ و با این حال پچورین که به تقدیر باور نداشت، خودش را قادر به توضیح آنچه اتفاق افتاده بود نیافت."),
            StoryParagraph("The following day, the Cossack who had killed Vulich barricaded himself in a hut, and no one dared to approach him, because he threatened to kill anyone who tried.", "روز بعد، قزاقی که وولیچ را کشته بود در کلبه‌ای خودش را بست و هیچ‌کس جرات نمی‌کرد نزدیکش شود، چون تهدید می‌کرد هر کسی که تلاش کند را می‌کشد."),
            StoryParagraph("Pechorin, driven by that same compulsion to test the limits of his own existence that had characterized his entire life, decided to enter the hut alone.", "پچورین که توسط همان اجبار به آزمودن مرزهای وجود خودش که تمام عمرش را مشخص کرده بود رانده می‌شد، تصمیم گرفت تنها وارد کلبه شود."),
            StoryParagraph("He walked through the door, and the Cossack aimed his pistol at him, and for a long moment, the two men stood facing each other in perfect stillness, and Pechorin felt, in that moment, the closest thing to peace that he had ever known.", "از در وارد شد و قزاق تپانچه‌اش را به سمتش نشانه گرفت و لحظه‌ای طولانی، دو مرد در سکوت کامل روبروی هم ایستادند و پچورین در آن لحظه، نزدیک‌ترین چیز به آرامشی که تا حالا شناخته بود را حس کرد."),
            StoryParagraph("Then, with a movement so swift that the Cossack had no time to react, Pechorin seized the pistol and subdued the man, and the siege was ended.", "بعد با حرکتی چنان سریع که قزاق فرصت واکنش نداشت، پچورین تپانچه را گرفت و مرد را مغلوب کرد و محاصره تمام شد."),
            StoryParagraph("The other officers, who had been watching from a safe distance, rushed forward to congratulate him, but Pechorin, who had faced death without flinching, found their admiration as meaningless as everything else.", "افسران دیگر که از فاصله‌ای امن تماشا می‌کردند، برای تبریک به جلو شتافتند، اما پچورین که بدون لرزش با مرگ روبرو شده بود، تحسینشان را به همان اندازه بی‌معنا مثل هر چیز دیگری یافت."),
            StoryParagraph("'I have tested fate,' he wrote in his journal, 'and I have found that it is indifferent; I have tested courage, and I have found that it is meaningless; I have tested life, and I have found that it is empty.'", "او در دفترش نوشت: «تقدیر را آزموده‌ام و یافته‌ام که بی‌تفاوت است؛ شجاعت را آزموده‌ام و یافته‌ام که بی‌معناست؛ زندگی را آزموده‌ام و یافته‌ام که پوچ است.»"),
            StoryParagraph("'And so I continue to live, not because I wish to, but because I have not yet found a sufficient reason to die.'", "«و اینگونه به زندگی ادامه می‌دهم، نه چون می‌خواهم، بلکه چون هنوز دلیل کافی برای مردن نیافته‌ام.»"),
            StoryParagraph("That was the final entry in Pechorin's journal, and it was, in its way, the perfect summation of his entire existence.", "این آخرین یادداشت در دفتر پچورین بود و به شیوه خودش، جمع‌بندی بی‌نقص کل وجودش بود."),
            StoryParagraph("He had lived, but he had not truly lived; he had felt, but he had not truly felt; he had loved, but he had not truly loved.", "او زندگی کرده بود اما واقعاً زندگی نکرده بود؛ احساس کرده بود اما واقعاً احساس نکرده بود؛ عشق ورزیده بود اما واقعاً عشق نورزیده بود."),
            StoryParagraph("And now, at the end of his narrative, he faced the future with the same indifference with which he had faced everything else, knowing that whatever happened, he would meet it without joy, without fear, and without meaning.", "و حالا، در پایان روایتش، با همان بی‌تفاوتی‌ای که با هر چیز دیگری روبرو شده بود با آینده روبرو می‌شد، چون می‌دانست هر چه پیش آید، بدون شادی، بدون ترس و بدون معنا با آن روبرو می‌شود."),
            StoryParagraph("That was the story of the fatalist, and it was the story of Pechorin himself, a man who had spent his life testing the limits of existence and had discovered that they led only to emptiness.", "این داستان فاتالیست بود و داستان خود پچورین بود، مردی که عمرش را صرف آزمودن مرزهای وجود کرده و کشف کرده بود که تنها به پوچی می‌رسند.")
        )
    )

    // ─────────── فصل ۶: پایان دفتر خاطرات ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The End of the Journal", titlePersian = "پایان دفتر خاطرات",
        paragraphs = listOf(
            StoryParagraph("I finished reading Pechorin's journal in the early hours of the morning, and I sat for a long time in silence, contemplating the strange and troubling figure it had revealed.", "خواندن دفتر پچورین را در ساعات اولیه صبح تمام کردم و مدت طولانی در سکوت نشستم و به چهره عجیب و نگران‌کننده‌ای که آشکار کرده بود اندیشیدم."),
            StoryParagraph("The man who emerged from these pages was neither hero nor villain, in the conventional sense of either term; he was something more disturbing — a human being who had been given every advantage and had found them all worthless.", "مردی که از این صفحات بیرون آمد نه قهرمان بود و نه شرور، به معنای متعارف هر یک از این دو واژه؛ چیز نگران‌کننده‌تری بود — انسانی که هر مزیتی به او داده شده و همه را بی‌ارزش یافته بود."),
            StoryParagraph("He was a man who could see through every illusion, and who had discovered that on the other side of illusion there was nothing at all.", "او مردی بود که می‌توانست از میان هر توهمی ببیند و کشف کرده بود که در طرف دیگر توهم هیچ چیز نیست."),
            StoryParagraph("He was a man who could manipulate every emotion in others, and who could not feel any emotion in himself.", "او مردی بود که می‌توانست هر احساسی را در دیگران دستکاری کند و نمی‌توانست هیچ احساسی در خودش حس کند."),
            StoryParagraph("He was a man who had destroyed everyone who loved him, not out of malice but out of the simple inability to love them back.", "او مردی بود که هر کسی را که دوستش داشت نابود کرد، نه از بدخواهی بلکه از ناتوانی ساده در دوست داشتن متقابل."),
            StoryParagraph("And this, I came to understand, was precisely what made him a hero of his time — not because he was admirable, but because he was representative.", "و این، فهمیدم، دقیقاً همان چیزی بود که او را قهرمان زمانش می‌کرد — نه چون تحسین‌برانگیز بود، بلکه چون نماینده بود."),
            StoryParagraph("Pechorin was the product of a society that had lost its faith without finding a new one, that had inherited the skepticism of one generation and the ambition of another, and that had found itself unable to commit to either.", "پچورین محصول جامعه‌ای بود که ایمانش را از دست داده بود بی‌آنکه ایمان جدیدی بیابد، که شک‌گرایی یک نسل و جاه‌طلبی نسل دیگری را به ارث برده بود و خودش را قادر به تعهد به هیچ‌کدام نیافته بود."),
            StoryParagraph("He was the product of an education that had taught him to question everything without teaching him what to believe in, and of a culture that had valued appearance over substance and conformity over authenticity.", "او محصول آموزشی بود که به او آموخته بود همه چیز را زیر سؤال ببرد بی‌آنکه به او بیاموزد به چه چیزی باور کند و محصول فرهنگی بود که ظاهر را بر جوهر و همرنگی را بر اصالت ارزش نهاده بود."),
            StoryParagraph("He was the product of a world in which the old values had died and the new ones had not yet been born, a world in which men like Pechorin were left to wander, searching for meaning in a universe that offered none.", "او محصول دنیایی بود که در آن ارزش‌های قدیمی مرده بودند و ارزش‌های جدید هنوز متولد نشده بودند، دنیایی که در آن مردانی مثل پچورین رها شده بودند تا سرگردان شوند و در جهانی که هیچ معنایی ارائه نمی‌داد معنا بجویند."),
            StoryParagraph("And yet, for all his emptiness, for all his cruelty, for all his inability to love or to be loved, Pechorin was not without a certain tragic dignity.", "و با این حال، با تمام پوچی‌اش، با تمام بی‌رحمی‌اش، با تمام ناتوانی‌اش در عشق ورزیدن یا دوست داشته شدن، پچورین بدون وقاری تراژیک خاصی نبود."),
            StoryParagraph("He had, at least, the courage to see himself clearly, to acknowledge his own deficiencies, to refuse the comfortable lies that most people tell themselves to make their lives bearable.", "او حداقل جرات دیدن خودش را با وضوح داشت، اقرار به کاستی‌های خودش، امتناع از دروغ‌های راحتی که بیشتر مردم به خودشان می‌گویند تا زندگی‌شان را تحمل‌پذیر کنند."),
            StoryParagraph("He had, at least, the honesty to record his failures without excuse or self-justification, to present himself to posterity not as he wished to be seen but as he truly was.", "او حداقل صداقت داشت که شکست‌هایش را بدون بهانه یا توجیه خودش ثبت کند، خودش را به آیندگان نه آنطور که می‌خواست دیده شود بلکه آنطور که واقعاً بود ارائه دهد."),
            StoryParagraph("And he had, at least, the sensitivity to feel his own emptiness as a wound, to suffer from his own inability to feel, to long for the very thing that he could not achieve.", "و او حداقل حساسیت داشت که پوچی خودش را مثل زخم حس کند، از ناتوانی خودش در احساس کردن رنج ببرد، برای همان چیزی که نمی‌توانست به دست آورد شوق داشته باشد."),
            StoryParagraph("This sensitivity, this suffering, this longing, was what distinguished Pechorin from the truly evil men of his time, and what made him, in the end, a figure of pity rather than of condemnation.", "این حساسیت، این رنج، این شوق، همان چیزی بود که پچورین را از مردان واقعاً شیطانی زمانش متمایز می‌کرد و او را در نهایت چهره‌ای از ترحم به جای محکومیت می‌ساخت."),
            StoryParagraph("He was not a monster; he was a man, a man who had been formed by forces beyond his control and who had found himself unable to transcend them.", "او هیولا نبود؛ او یک انسان بود، انسانی که توسط نیروهایی فراتر از کنترلش شکل گرفته بود و خودش را قادر به فراتر رفتن از آن‌ها نیافته بود."),
            StoryParagraph("And if there was a lesson to be drawn from his life, it was perhaps this: that intelligence without love is a curse, that freedom without purpose is a prison, and that a man who cannot connect with others cannot truly live.", "و اگر درسی از زندگی‌اش گرفته می‌شد، شاید این بود: هوش بدون عشق نفرین است، آزادی بدون هدف زندان است و مردی که نمی‌تواند با دیگران ارتباط برقرار کند نمی‌تواند واقعاً زندگی کند."),
            StoryParagraph("Pechorin was a hero of his time, but he was also a warning to all times: a reminder of what happens to a human being who has been given everything and has found that everything is not enough.", "پچورین قهرمان زمانش بود، اما هشداری برای همه زمان‌ها هم بود: یادآوری از آنچه بر سر انسانی می‌آید که همه چیز به او داده شده و یافته که همه چیز کافی نیست."),
            StoryParagraph("When I finally closed the journal and returned it to Maxim Maximych, the old captain asked me what I had thought of it.", "وقتی بالاخره دفتر را بستم و به ماکسیم ماکسیمیچ برگرداندم، ناخدای پیر پرسید چه فکری درباره‌اش کردم."),
            StoryParagraph("'I do not know,' I said honestly. 'I cannot decide whether to admire him or to pity him, or whether perhaps both responses are appropriate.'", "صادقانه گفتم: «نمی‌دانم. نمی‌توانم تصمیم بگیرم تحسینش کنم یا برایش ترحم کنم، یا شاید هر دو پاسخ مناسب باشند.»"),
            StoryParagraph("'That,' said Maxim Maximych, 'is exactly how I have always felt about him. He was the best and the worst of men at the same time, and I never knew which side would show itself at any given moment.'", "ماکسیم ماکسیمیچ گفت: «این دقیقاً همانطور است که من همیشه درباره‌اش حس کرده‌ام. او همزمان بهترین و بدترین مردان بود و هرگز نمی‌دانستم کدام طرفش در هر لحظه معین ظاهر می‌شود.»"),
            StoryParagraph("'But I will tell you one thing,' he added, 'and I say this as a man who has known him longer than almost anyone: Pechorin was not wicked, and he was not good. He was simply lost.'", "اضافه کرد: «اما یک چیز به تو می‌گویم و این را به‌عنوان مردی می‌گویم که او را بیشتر از تقریباً هر کسی می‌شناخته: پچورین شرور نبود و خوب هم نبود. او فقط گمگشته بود.»"),
            StoryParagraph("Lost — that was perhaps the most precise word for Pechorin, and for his generation, and perhaps for many generations since.", "گمگشته — شاید این دقیق‌ترین کلمه برای پچورین بود و برای نسل او و شاید برای بسیاری نسل‌های بعد از او."),
            StoryParagraph("They were a generation that had lost its way in a world that offered no maps, no guides, no destinations worth reaching.", "آن‌ها نسلی بودند که راهش را در دنیایی گم کرده بود که هیچ نقشه‌ای، هیچ راهنمایی، هیچ مقصد ارزشمندی برای رسیدن ارائه نمی‌داد."),
            StoryParagraph("They were a generation that had been taught to question everything and had found that the answers led nowhere.", "آن‌ها نسلی بودند که یاد گرفته بود همه چیز را زیر سؤال ببرد و یافته بود که پاسخ‌ها به هیچ‌جا نمی‌رسند."),
            StoryParagraph("They were a generation that had been given the freedom to choose and had found that there was nothing worth choosing.", "آن‌ها نسلی بودند که آزادی انتخاب به آن‌ها داده شده و یافته بودند که چیزی ارزش انتخاب کردن ندارد."),
            StoryParagraph("And Pechorin was the most brilliant, the most sensitive, the most honest representative of that generation, and therefore the most tragic.", "و پچورین درخشان‌ترین، حساس‌ترین، صادق‌ترین نماینده آن نسل بود و بنابراین تراژیک‌ترین."),
            StoryParagraph("When I finally took my leave of Maxim Maximych, the old captain embraced me with a warmth that I had not expected, and I saw, in his eyes, the same sorrow that I had seen when Pechorin had left him.", "وقتی بالاخره از ماکسیم ماکسیمیچ خداحافظی کردم، ناخدای پیر با گرمایی که انتظارش را نداشتم در آغوشم گرفت و در چشمانش همان اندوهی را دیدم که وقتی پچورین ترکش کرده بود دیده بودم."),
            StoryParagraph("'Take care of yourself,' he said, 'and remember: do not be like Pechorin. Find something to believe in, find someone to love, find a reason to live. Otherwise, you will end up alone and empty, like him.'", "گفت: «مراقب خودت باش و یادت باشد: مثل پچورین نباش. چیزی برای باور کردن پیدا کن، کسی برای دوست داشتن، دلیلی برای زندگی. وگرنه، مثل او تنها و پوچ تمام می‌کنی.»"),
            StoryParagraph("I promised that I would remember, and I meant it, though I knew, even as I made the promise, that such things are easier said than done.", "قول دادم یادم می‌ماند و منظورم بود، هرچند می‌دانستم، حتی همان‌وقت که قول می‌دادم، که چنین چیزهایی گفتنش از انجام دادنش آسان‌تر است."),
            StoryParagraph("And so I departed from the Caucasus, carrying with me the story of Pechorin, a story that would haunt me for the rest of my life.", "و اینگونه از قفقاز رفتم و داستان پچورین را با خودم بردم، داستانی که تا آخر عمرم تسخیرم می‌کرد."),
            StoryParagraph("It was a story of a man who had been given everything and had valued nothing, a man who had searched for meaning in every corner of the world and had found it nowhere.", "داستان مردی بود که همه چیز به او داده شده و هیچ چیز را ارزشمند نشمرده بود، مردی که در هر گوشه دنیا معنا جسته و هیچ‌جا نیافته بود."),
            StoryParagraph("It was a story of a generation that had lost its way and could not find it again.", "داستان نسلی بود که راهش را گم کرده و نمی‌توانست دوباره پیدایش کند."),
            StoryParagraph("And it was a story that I knew, with a certainty that I could not explain, would be told and retold for generations to come, because it was not merely the story of one man but the story of an age.", "و داستانی بود که می‌دانستم، با اطمینانی که نمی‌توانستم توضیح دهم، برای نسل‌های آینده گفته و بازگو خواهد شد، چون نه فقط داستان یک مرد بلکه داستان یک عصر بود."),
            StoryParagraph("The hero of our time, Pechorin had been called, and the phrase was apt, for every age has its Pechorin, its men of intelligence and emptiness, its brilliant failures, its tragic seekers after meaning in a world that has none.", "قهرمان زمان ما، پچورین نامیده شده بود و این عبارت بجا بود، چون هر عصر پچورین خودش را دارد، مردان هوش و پوچی‌اش، شکست‌های درخشانش، جستجوگران تراژیک معنایی در دنیایی که هیچ ندارد."),
            StoryParagraph("And so the story of Pechorin ends, but the questions it raises continue, and will continue, as long as men have the courage to ask them.", "و اینگونه داستان پچورین پایان می‌یابد، اما پرسش‌هایی که مطرح می‌کند ادامه دارند و ادامه خواهند داشت، تا وقتی مردان جرات پرسیدنشان را داشته باشند."),
            StoryParagraph("Who am I? Why am I here? What is the meaning of my life?", "من کی هستم؟ چرا اینجا هستم؟ معنای زندگی‌ام چیست؟"),
            StoryParagraph("Pechorin never found the answers to these questions, and perhaps there are no answers to find.", "پچورین هرگز پاسخ این پرسش‌ها را نیافت و شاید هیچ پاسخی برای یافتن وجود ندارد."),
            StoryParagraph("But the questions themselves, and the courage to ask them, and the honesty to admit that they may have no answers — perhaps that is the only heroism available to us in this time, or in any time.", "اما خود پرسش‌ها و جرات پرسیدنشان و صداقت اقرار به اینکه ممکن است هیچ پاسخی نداشته باشند — شاید این تنها قهرمانی موجود برای ما در این زمان، یا در هر زمانی باشد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the search continues, as it always has, and as it always will.", "اما جستجو ادامه دارد، همانطور که همیشه داشته و همانطور که همیشه خواهد داشت.")
        )
    )
}